// Process state = ek simple toggle hai.
// Ek chhota sa state machine socho:

let state = 'New';

function tick() {
  if (state === 'New')      state = 'Ready';
  else if (state === 'Ready') state = 'Running';
  else if (state === 'Running') {
    if (needIO()) state = 'Waiting';   // I/O ka wait
    else state = 'Terminated';
  } else if (state === 'Waiting') {
    state = 'Ready';                    // I/O aaya → wapas line
  }
  console.log('ab state:', state);
}

