// FCFS: order hi kaam ki baat hai.
function fcfs(procs) {
  return procs.slice().sort((a, b) => a.arrival - b.arrival);
}

// SJF: chhota (duration) pehle.
function sjf(procs) {
  return procs.slice().sort((a, b) => a.duration - b.duration);
}

// SJF optimal hai (avg wait), par future pata nahi +
// chhote aate rahein to bada kabhi turn nahi paega (starvation).
// Aging: wait badha to priority badha — bhookh khatam.

// Round Robin — circular queue, equal quantum.
const queue = ['P1', 'P2', 'P3', 'P4'];
const QUANTUM = 2;

function rr(procs, quantum = QUANTUM) {
  let i = 0;
  let remain = procs.map(p => p.duration);
  let t = 0;
  while (remain.some(r => r > 0)) {
    if (remain[i] > 0) {
      const used = Math.min(remain[i], quantum);
      remain[i] -= used; t += used;   // ik quantum diya
    }
    i = (i + 1) % procs.length;       // agla, circular
  }
}
// quantum chhota = zyada switch = overhead.
// quantum bada = sab saamne khatam, peechle intezaar (FCFS).

// Aging: wait badhne par priority badhao.
function aging(procs) {
  return procs.map(p => ({
    ...p,
    priority: p.priority + Math.floor(p.wait / 100) // wait → priority
  })).sort((a, b) => b.priority - a.priority);
}

// CFS (Linux): sabse kam vruntime wala.
// vruntime = kitna CPU time mil chuka (normalized).
function cfsSelect(procs) {
  return procs.reduce((min, p) =>
    p.vruntime < min.vruntime ? p : min, procs[0]);
}
