// FCFS — bina soch samjhe, aate hi serve.
function fcfsDisk(requests) {
  let head = 40, total = 0;
  for (const r of requests) { total += Math.abs(r - head); head = r; }
  return total; // seek total
}

// SCAN — head aage, sorted requests raste mein.
function scanDisk(requests, dir = 1) {
  const sorted = requests.slice().sort((a, b) => a - b);
  // head se aage wale pehle, phir uske baad...
  return sorted.filter(r => dir > 0 ? r > head : r < head);
}
